// Читает SSE-тело из fetch Response, вызывает onEvent({event, data}) на каждое событие.
async function readSSE(res, onEvent) {
  const reader = res.body.getReader();
  const decoder = new TextDecoder();          // по умолчанию UTF-8
  let buf = "";
  for (;;) {
    const { value, done } = await reader.read();
    if (done) break;
    buf += decoder.decode(value, { stream: true });
    // CRLF и CR -> LF; висящий в конце "\r" придерживаем: "\n" может прийти в следующем чанке
    const tail = buf.endsWith("\r") ? "\r" : "";
    buf = (tail ? buf.slice(0, -1) : buf).replace(/\r\n?/g, "\n");
    let i;
    while ((i = buf.indexOf("\n\n")) !== -1) {  // пустая строка = конец события
      const raw = buf.slice(0, i);
      buf = buf.slice(i + 2);
      const ev = parseEvent(raw);
      if (ev) onEvent(ev);
    }
    buf += tail;
  }
}

function parseEvent(raw) {
  let event = "message";
  const data = [];
  for (const line of raw.split("\n")) {
    if (line === "" || line.startsWith(":")) continue;   // ":" = комментарий / keep-alive
    const c = line.indexOf(":");
    const field = c === -1 ? line : line.slice(0, c);
    let value = c === -1 ? "" : line.slice(c + 1);
    if (value.startsWith(" ")) value = value.slice(1);
    if (field === "event") event = value;
    else if (field === "data") data.push(value);
  }
  return data.length ? { event, data: data.join("\n") } : null;
}

// Читает поток Anthropic Messages. Бросает ошибку, если поток кончился раньше времени.
async function consumeClaude(res, onText) {
  let stopReason = null, usage = null, finished = false;
  await readSSE(res, ({ event, data }) => {
    const msg = JSON.parse(data);
    switch (msg.type) {
      case "message_start": usage = msg.message.usage; break;
      case "content_block_delta":
        if (msg.delta.type === "text_delta") onText(msg.delta.text);
        break;
      case "message_delta":
        stopReason = msg.delta.stop_reason;
        usage = { ...usage, ...msg.usage };        // счётчики здесь накопительные
        break;
      case "message_stop": finished = true; break;
      case "error": throw new Error(msg.error.type);  // например overloaded_error после 200
      default: break;                            // ping и будущие типы событий
    }
  });
  if (!finished) throw new Error("stream ended before message_stop");
  return { stopReason, usage };
}

