import { useCallback, useRef, useState } from "react";

export function useStreamedText() {
  const [text, setText] = useState("");
  const pending = useRef("");                   // дельты, которых ещё нет на экране
  const frame = useRef<number | null>(null);

  const flush = useCallback(() => {
    frame.current = null;
    const chunk = pending.current;
    pending.current = "";
    if (chunk) setText(prev => prev + chunk);  // один рендер на всё, что пришло с прошлого кадра
  }, []);

  const push = useCallback((delta: string) => {
    pending.current += delta;
    if (frame.current === null) frame.current = requestAnimationFrame(flush);
  }, [flush]);

  const finish = useCallback(() => {           // в фоновой вкладке rAF на паузе: сбрасываем явно
    if (frame.current !== null) cancelAnimationFrame(frame.current);
    flush();
  }, [flush]);

  return { text, push, finish };
}

